fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, w / 2);
        host::display::state_set(2, h / 2);
        host::display::state_set(3, 4);
        host::display::state_set(4, 3);
        host::display::state_set(9, h / 2 - 30);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(8) == 0;
    host::display::state_set(8, down);
    let phase: i32 = host::display::state_get(7);
    if phase == 1 {
        host::display::clear(0x101018);
        if host::display::state_get(5) >= 5 {
            host::display::draw_string(160, 190, "YOU WIN", 0x00ff88, 4);
        } else {
            host::display::draw_string(150, 190, "CPU WINS", 0xff4040, 4);
        }
        host::display::draw_number(200, 250, host::display::state_get(5), 0xffffff, 3);
        host::display::draw_number(280, 250, host::display::state_get(6), 0xff8800, 3);
        host::display::draw_string(150, 320, "TAP TO REMATCH", 0x808080, 2);
        if tap {
            host::display::state_set(5, 0);
            host::display::state_set(6, 0);
            host::display::state_set(7, 0);
            host::display::state_set(0, 0);
        }
    } else {
        let mut bx: i32 = host::display::state_get(1);
        let mut by: i32 = host::display::state_get(2);
        let mut vx: i32 = host::display::state_get(3);
        let mut vy: i32 = host::display::state_get(4);
        let mut py: i32 = host::display::pointer_y() - 30;
        if py < 0 { py = 0; }
        if py > h - 60 { py = h - 60; }
        let mut ay: i32 = host::display::state_get(9);
        let bc: i32 = by + 5;
        if bc > ay + 34 { ay = ay + 3; }
        if bc < ay + 26 { ay = ay - 3; }
        if ay < 0 { ay = 0; }
        if ay > h - 60 { ay = h - 60; }
        host::display::state_set(9, ay);
        bx = bx + vx;
        by = by + vy;
        if by < 0 { by = 0; vy = -vy; }
        if by > h - 10 { by = h - 10; vy = -vy; }
        if bx < 20 && bx > 6 && vx < 0 && by + 10 > py && by < py + 60 {
            bx = 20;
            vx = -vx;
        }
        if bx > w - 30 && bx < w - 16 && vx > 0 && by + 10 > ay && by < ay + 60 {
            bx = w - 30;
            vx = -vx;
        }
        if bx < -12 {
            host::display::state_set(6, host::display::state_get(6) + 1);
            bx = w / 2;
            by = h / 2;
            vx = 4;
            vy = 3;
        }
        if bx > w + 2 {
            host::display::state_set(5, host::display::state_get(5) + 1);
            bx = w / 2;
            by = h / 2;
            vx = -4;
            vy = 3;
        }
        host::display::state_set(1, bx);
        host::display::state_set(2, by);
        host::display::state_set(3, vx);
        host::display::state_set(4, vy);
        if host::display::state_get(5) >= 5 || host::display::state_get(6) >= 5 {
            host::display::state_set(7, 1);
        }
        host::display::clear(0x000000);
        let mut ny: i32 = 0;
        while ny < h {
            host::display::fill_rect(w / 2 - 1, ny, 2, 8, 0x303030);
            ny = ny + 16;
        }
        host::display::fill_rect(12, py, 8, 60, 0xffffff);
        host::display::fill_rect(w - 20, ay, 8, 60, 0xff8800);
        host::display::fill_rect(bx, by, 10, 10, 0x00ff88);
        host::display::draw_number(w / 2 - 60, 10, host::display::state_get(5), 0xffffff, 3);
        host::display::draw_number(w / 2 + 36, 10, host::display::state_get(6), 0xff8800, 3);
    }
    host::display::present();
}
